// Reserved username prefixes that Clerk users must not be allowed to claim.
// `community-` is auto-generated by Skills Hunt for unclaimed Directory profiles
// (see directory_profiles.unclaimed_handle). Allowing a real user to register
// with this prefix would let them impersonate a community-generated profile.
//
// Defense-in-depth: in addition to this server-side check, Clerk must reject
// the prefix at sign-up — configure
// `usernames.disallowed_prefixes = ["community-"]` in the Clerk dashboard.
// See rule 123-environment-configuration-rules.mdc.

export const SKILLS_HUNT_RESERVED_USERNAME_PREFIXES: readonly string[] = ['community-'];

export type UsernamePolicyResult =
  | { ok: true }
  | { ok: false; reason: 'reserved_prefix'; matchedPrefix: string };

export function evaluateUsernamePolicy(username: string): UsernamePolicyResult {
  const normalized = username.trim().toLowerCase();
  for (const prefix of SKILLS_HUNT_RESERVED_USERNAME_PREFIXES) {
    if (normalized.startsWith(prefix)) {
      return { ok: false, reason: 'reserved_prefix', matchedPrefix: prefix };
    }
  }
  return { ok: true };
}

export function isReservedUsername(username: string | null | undefined): boolean {
  if (!username) return false;
  return evaluateUsernamePolicy(username).ok === false;
}
